let method = $json.method;
if (!method) { method = $json.headers?.[':method'] || 'POST'; }
return [{ json: { ...$json, method: method } }];

const body = $json.body;
if (!body || typeof body !== 'object') throw new Error('400: Request body is missing or invalid');

const safeArray = v => Array.isArray(v) ? v : (v ? [v] : []);
const normaliseAge = arr => arr.map(v => {
  if (v === 'Kids')      return 'Kids_0_12';
  if (v === 'Teens')     return 'Teens_13_19';
  if (v === 'Adults')    return 'Adults_20_39';
  if (v === 'MiddleAge') return 'Adults_40_59';
  if (v === 'Seniors')   return 'Seniors_60plus';
  return v;
});

const flexDates = body.flexDates === 'yes' || body.flexDates === true || body.flexDates === 'true';

const destinationCity = (body.destinationCity || body.adventureDestination || '').trim();
if (!destinationCity) throw new Error('400: destinationCity is required');

if (!flexDates) {
  const startDate = (body.startDate || '').trim();
  const endDate   = (body.endDate   || '').trim();
  if (!startDate || !endDate) throw new Error('400: startDate and endDate are required');
  const d1 = new Date(startDate), d2 = new Date(endDate);
  if (isNaN(d1) || isNaN(d2)) throw new Error('400: Invalid date format');
  if (d2 < d1) throw new Error('400: endDate must be on or after startDate');
}

return [{ json: {
  departureLocation:    (body.departureLocation || 'Not specified').trim(),
  adventureDestination: destinationCity,
  // adventure-specific
  activityType:  body.activityType || 'Hiking',
  intensity:     body.difficulty   || body.intensity || 'Intermediate',
  environment:   safeArray(body.environment),
  // new fields
  travelPace:    body.travelPace  || 'Balanced',
  budgetTier:    body.budgetTier  || 'Standard',
  flexDates,
  // standard
  startDate:     (body.startDate || '').trim(),
  endDate:       (body.endDate   || '').trim(),
  tripType:      body.tripType   || 'Not specified',
  groupSize:     body.groupSize  || '1',
  ageRange:      normaliseAge(safeArray(body.ageRange)),
  travelMode:    body.travelMode || 'flight',
  budget:        body.budget     || '0',
  email:         (body.email     || '').trim()
}}];

const {
  departureLocation, adventureDestination, activityType, intensity,
  environment, travelPace, budgetTier, flexDates, travelMode,
  startDate, endDate, tripType, groupSize, ageRange, budget, email
} = $json;

const fmt = v => Array.isArray(v) && v.length ? v.join(', ') : 'No preference';

const paceLabel = {
  Relaxed:  'Relaxed & scenic (max 2 activities/day, recovery time, shorter distances)',
  Balanced: 'Balanced (3–4 activities/day, mix of challenging and easy)',
  Active:   'Packed & intense (full days, maximum challenge, back-to-back activities)',
}[travelPace] || travelPace;

const tierLabel = {
  Economy:  'Economy — budget gear rental, basic guesthouses, self-organised, local guides',
  Standard: 'Standard — quality outfitters, guided tours, comfortable lodges or basecamp',
  Elite:    'Elite — private guides, premium gear, luxury lodges, exclusive permits and access',
}[budgetTier] || budgetTier;


const modeLabel = {
  flight: 'Flying — include flight recommendations, departure airport, airline and booking links',
  drive:  'Driving — include road trip route, scenic stops, driving time estimates, parking at trailheads. Do NOT recommend flights.',
  train:  'Train — include rail connections, journey time, station-to-destination tips. Do NOT recommend flights.',
  bus:    'Bus — include bus routes and operators, journey time, terminal information. Do NOT recommend flights.',
  ferry:  'Ferry — include ferry crossings, operator names, port logistics. Do NOT recommend flights.',
}[travelMode] || 'Flying';

const dateLine = flexDates
  ? 'Flexible — suggest the optimal season for this activity and destination'
  : (startDate && endDate ? `${startDate} to ${endDate}` : 'Not specified');

const prompt = `Please create a complete adventure trip itinerary with the following details:

- Departure: ${departureLocation}
- Travel Mode: ${modeLabel}
- Destination: ${adventureDestination}
- Dates: ${dateLine}
- Activity Type: ${activityType}
- Difficulty / Intensity: ${intensity}
- Preferred Environments: ${fmt(environment)}
- Trip Type: ${tripType}
- Travel Pace: ${paceLabel}
- Plan Tier: ${tierLabel}
- Total Budget: $${budget} USD
- Group Size: ${groupSize}
- Age Ranges: ${fmt(ageRange)}

Please follow all formatting and content rules from the system prompt exactly.`;

return [{ json: {
  departureLocation, adventureDestination, activityType, intensity,
  environment, travelPace, budgetTier, flexDates, travelMode,
  startDate, endDate, tripType, groupSize, ageRange, budget, email, prompt
}}];

// ── FIX 4: Added OpenAI empty response guard ──
// ── FIX 5: Added markdown fence stripping ──
const rawContent = $node['OpenAI'].json?.message?.content;

if (!rawContent || rawContent.trim() === '') {
  const reason = $node['OpenAI'].json?.message?.finish_reason || 'unknown';
  throw new Error(`OpenAI returned empty content. Finish reason: ${reason}. Check API quota or prompt length.`);
}

// Normalise literal \t (AI sometimes outputs backslash-t instead of real tab)
// then strip markdown code fences
const itineraryRaw = rawContent
  .replace(/\\t/g, '\t')
  .replace(/```[\w]*\n?/g, '').replace(/```/g, '').trim();

const itineraryLines = itineraryRaw.split('\n');
let formattedItinerary = '';
let inDailySchedule = false;
let inCostSummary   = false;
let scheduleLines   = [];
let costSummaryRows = [];

const formatDailySchedule = (lines) => {
  let output = '<strong style="font-size:16px;color:#2a4a6e;display:block;margin:15px 0 5px 0;">Daily Schedule:</strong>';
  const joined = lines.join(' ');
  const daySections = joined.match(/(Day \d+:.*?)(?=(Day \d+:|$))/g);
  if (!daySections) return output + '<br>';
  daySections.forEach((dayMatch, index) => {
    const dayLabelMatch = dayMatch.match(/(Day \d+:[^-]*)/);
    if (!dayLabelMatch) return;
    const dayLabel = dayLabelMatch[1].trim();
    const subItems = dayMatch.match(/- (Morning|Afternoon|Evening):.*?(?=(Day \d+:|- (Morning|Afternoon|Evening):|$))/g);
    output += `<strong>${dayLabel}</strong>`;
    if (subItems) { output += `<div style="margin:4px 0 8px 12px;">${subItems.map(i => i.trim()).join('<br>')}</div>`; }
    if (index < daySections.length - 1) output += '<br>';
  });
  return output + '<br>';
};

for (let line of itineraryLines) {
  line = line.trim();
  if (!line) {
    if (inDailySchedule) { formattedItinerary += formatDailySchedule(scheduleLines); inDailySchedule = false; scheduleLines = []; }
    else if (inCostSummary) { inCostSummary = false; formattedItinerary += `<table style="border-collapse:collapse;width:100%;margin:10px 0;font-size:14px;">${costSummaryRows.join('')}</table><br>`; costSummaryRows = []; }
    else { formattedItinerary += '<br>'; }
    continue;
  }
  const lower = line.toLowerCase();
  if (lower.startsWith('daily schedule:')) { inDailySchedule = true; scheduleLines = []; continue; }
  if (inDailySchedule) { scheduleLines.push(line); continue; }
  if (lower.startsWith('cost summary:')) { formattedItinerary += `<strong style="font-size:16px;color:#2a4a6e;display:block;margin:15px 0 5px 0;">Cost Summary:</strong>`; inCostSummary = true; continue; }
  if (inCostSummary && line.includes('\t')) {
    const parts = line.split('\t').map(s => s.trim());
    const cat = parts[0] || ''; const cost = parts[1] || '';
    const isBold = cat.startsWith('Total') || cat.startsWith('Remaining Budget');
    const style = isBold ? 'border:1px solid #e0e0e0;padding:8px;background:#f0f0f0;font-weight:bold;' : 'border:1px solid #e0e0e0;padding:8px;';
    costSummaryRows.push(`<tr><td style="${style}">${cat}</td><td style="${style}">${cost}</td></tr>`);
    continue;
  }
  if (inCostSummary) { inCostSummary = false; formattedItinerary += `<table style="border-collapse:collapse;width:100%;margin:10px 0;font-size:14px;">${costSummaryRows.join('')}</table><br>`; costSummaryRows = []; }
  if (line.endsWith(':')) { formattedItinerary += `<strong style="font-size:16px;color:#2a4a6e;display:block;margin:15px 0 5px 0;">${line}</strong>`; }
  else { formattedItinerary += `${line}<br>`; }
}
if (inDailySchedule && scheduleLines.length > 0) formattedItinerary += formatDailySchedule(scheduleLines);
if (costSummaryRows.length > 0) formattedItinerary += `<table style="border-collapse:collapse;width:100%;margin:10px 0;font-size:14px;">${costSummaryRows.join('')}</table><br>`;

return [{ json: { ...$json, itinerary: formattedItinerary } }];

const prep = $node['Prepare Adventure Data'].json;
const fmt  = $node['Format Daily Schedule'].json;
if (!prep || !fmt) throw new Error('Adventure Info: missing data from upstream nodes.');
if (!fmt.itinerary || fmt.itinerary.trim() === '') throw new Error('Adventure Info: empty itinerary.');
return [{ json: {
  departureLocation:    prep.departureLocation,
  adventureDestination: prep.adventureDestination,
  activityType:         prep.activityType,
  intensity:            prep.intensity,
  environment:          prep.environment,
  travelPace:           prep.travelPace,
  budgetTier:           prep.budgetTier,
  flexDates:            prep.flexDates,
  startDate:            prep.startDate,
  endDate:              prep.endDate,
  tripType:             prep.tripType,
  groupSize:            prep.groupSize,
  ageRange:             prep.ageRange,
  travelMode:           prep.travelMode,
  budget:               prep.budget,
  email:                prep.email,
  itinerary:            fmt.itinerary
}}];

const destination  = $json.adventureDestination || 'Your Destination';
const departure    = $json.departureLocation    || 'Not specified';
const flexDates    = $json.flexDates            || false;
const travelDates  = flexDates
  ? 'Flexible — Genie will suggest the optimal season'
  : `${$json.startDate||'N/A'} to ${$json.endDate||'N/A'}`;
const budget       = $json.budget      || 'N/A';
const groupSize    = $json.groupSize   || 'N/A';
const tripType     = $json.tripType    || 'N/A';
const activityType = $json.activityType|| 'Not specified';
const intensity    = $json.intensity   || 'Not specified';
const travelPace   = $json.travelPace  || '';
const budgetTier   = $json.budgetTier  || 'Standard';
const ageRange     = Array.isArray($json.ageRange) ? $json.ageRange.join(', ') : ($json.ageRange||'');
const itineraryContent = $json.itinerary || 'Itinerary details not available.';

const tierBadge = { Economy: '🟢 Economy', Standard: '🔵 Standard', Elite: '⭐ Elite' }[budgetTier] || budgetTier;
const paceLabel = { Relaxed: '🌅 Relaxed', Balanced: '🌊 Balanced', Active: '🏄 Active' }[travelPace] || travelPace;

const metaRow = (label, value) =>
  `<p style="color:#333;font-size:15px;margin:8px 0;line-height:1.5;"><strong style="color:#023e8a;">${label}:</strong> ${value}</p>`;

const emailHtml = `
<div style="font-family:'Helvetica Neue',Arial,sans-serif;max-width:660px;margin:0 auto;background:#f8fafc;padding:24px;border-radius:12px;">
  <div style="background:linear-gradient(105deg,#023e8a,#0077b6);padding:26px 28px;border-radius:10px 10px 0 0;text-align:center;">
    <h1 style="color:#fff;margin:0;font-size:26px;font-family:Georgia,serif;">🏔️ Your Adventure Itinerary</h1>
    <p style="color:rgba(255,255,255,0.8);margin:6px 0 0;font-size:14px;">Generated by Voyage Genie · ${tierBadge}</p>
  </div>
  <div style="background:#fff;padding:28px;border-radius:0 0 10px 10px;border:1px solid #e2e8f0;border-top:none;">
    <h2 style="color:#023e8a;font-size:18px;margin:0 0 16px;border-bottom:2px solid #eaf4fb;padding-bottom:10px;">Trip Overview</h2>
    ${metaRow('📍 Destination', destination)}
    ${metaRow('✈️ Departing from', departure)}
    ${metaRow('📅 Dates', travelDates)}
    ${metaRow('🏞️ Activity', `${activityType} · ${intensity}`)}
    ${metaRow('🧳 Trip Type', tripType)}
    ${paceLabel ? metaRow('⚡ Travel Pace', paceLabel) : ''}
    ${metaRow('⭐ Plan Tier', tierBadge)}
    ${metaRow('👥 Group Size', groupSize)}
    ${ageRange ? metaRow('👨‍👩‍👧 Age Ranges', ageRange) : ''}
    ${metaRow('💵 Budget', '$' + budget)}
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:20px 0;">
    <h3 style="color:#023e8a;font-size:16px;margin:0 0 14px;">Your Itinerary</h3>
    <div style="background:#f8fafc;padding:20px;border-radius:8px;font-size:14px;line-height:1.7;color:#1e293b;border:1px solid #e2e8f0;">
      ${itineraryContent}
    </div>
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:24px 0 16px;">
    <p style="color:#64748b;font-size:12px;text-align:center;margin:0;">
      Generated by <strong>Voyage Genie</strong> 🌟 &nbsp;|&nbsp; Plan Less, Explore More
    </p>
  </div>
</div>`;

const sessionId = [Date.now().toString(36), Math.random().toString(36).slice(2,7)].join('-');
const subject   = `Your ${tierBadge} Adventure Itinerary for ${destination} – Voyage Genie`;

const formData = {
  departureLocation:    departure,
  destinationCity:      destination,
  adventureDestination: destination,
  activityType, intensity, travelPace, budgetTier, flexDates,
  tripType, groupSize, budget,
  startDate: $json.startDate || '',
  endDate:   $json.endDate   || '',
  ageRange:  $json.ageRange  || [],
  environment: $json.environment || []
};

return [{ json: {
  sessionId,
  itineraryHtml:   itineraryContent,  // clean content for frontend display
  emailHtml:       emailHtml,         // full branded wrapper for email sending
  resolvedEmail:   ($json.email || '').trim(),
  resolvedSubject: subject,
  resolvedMessage: emailHtml,
  formData
}}];

// ── FIX 10: Retry logic + skip-if-no-email (same as tropical/airbnb fixed versions) ──
const EMAIL_WEBHOOK = 'https://exodonprofits.app.n8n.cloud/webhook/send-email';
const MAX_RETRIES   = 2;
const RETRY_DELAY   = 1500;

const payload = {
  resolvedEmail:   $json.resolvedEmail,
  resolvedSubject: $json.resolvedSubject,
  resolvedMessage: $json.resolvedMessage
};

if (!payload.resolvedEmail || payload.resolvedEmail === '') {
  return $input.all();
}

const sleep = (ms) => new Promise(r => setTimeout(r, ms));
let lastError;
for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
  try {
    await $http({ method: 'POST', url: EMAIL_WEBHOOK, body: payload, headers: { 'Content-Type': 'application/json' } });
    return $input.all();
  } catch (err) {
    lastError = err;
    if (attempt < MAX_RETRIES) await sleep(RETRY_DELAY);
  }
}
console.error(`Email delivery failed after ${MAX_RETRIES} attempts: ${lastError?.message}`);
return $input.all();

return [{ json: {
  sessionId:     $json.sessionId,
  redirectUrl:   $json.redirectUrl,
  itineraryData: $json.itineraryData,
  itineraryHtml: $json.itineraryHtml,
  emailHtml:     $json.emailHtml
}}];

let method = $json.method;
if (!method) { method = $json.headers?.[':method'] || 'POST'; }
return [{ json: { ...$json, method: method } }];

// ── FIX 11: New Suggestion now has its own pipeline (was incorrectly routing into main Code node) ──
const body = $json.body || $json;
const destination  = body.destinationCity  || body.adventureDestination || 'unknown';
const activityType = body.activityType     || 'Hiking';
const intensity    = body.difficulty       || body.intensity || 'Intermediate';
const budget       = body.budget           || '0';
const tripType     = body.tripType         || 'Not specified';
const startDate    = body.startDate        || '';
const endDate      = body.endDate          || '';

const prompt = `The user has an adventure itinerary for ${destination} featuring ${activityType} at ${intensity} difficulty. Budget: $${budget}. Trip type: ${tripType}${startDate ? `. Dates: ${startDate} to ${endDate}` : ''}.

Suggest 3 alternative adventure destinations that:
- Offer a similar ${activityType} experience
- Match the ${intensity} difficulty level
- Fit within the same budget range
- Suit a ${tripType} traveler

For each destination provide:
- Destination name and country
- Why it's a great ${activityType} alternative to ${destination}
- Best time to visit
- Estimated total cost (flights + accommodation + activities for the trip duration)
- Top 3 specific activities or trails
- A search link (Viator, AllTrails, or destination tourism site)

Format each suggestion with a clear bold heading and bullet points.`;

return [{ json: { ...body, prompt } }];

const rawContent = $node['OpenAI New Suggestion'].json?.message?.content;
if (!rawContent || rawContent.trim() === '') throw new Error('OpenAI New Suggestion returned empty content.');
const sessionId = [Date.now().toString(36), Math.random().toString(36).slice(2,7)].join('-');
const suggestionsHtml = rawContent.trim().replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>');
return [{ json: { sessionId, suggestions: rawContent.trim(), suggestionsHtml, itineraryHtml: suggestionsHtml } }];
